  const ranges = [];
  for (const i of changes) {
    const start = Math.max(0, i - context);
    const end = Math.min(script.length, i + context + 1);
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous[1]) previous[1] = Math.max(previous[1], end);
    else ranges.push([start, end]);
  }
  return ranges.map(([start, end]) => {
    const before = script.slice(0, start);
    const entries = script.slice(start, end);
    const oldBegin = before.filter(e => e.op !== 'insert').length;
    const newBegin = before.filter(e => e.op !== 'delete').length;
    const oldLines = entries.filter(e => e.op !== 'insert').length;
    const newLines = entries.filter(e => e.op !== 'delete').length;
    return {
      oldStart: oldBegin + (oldLines ? 1 : 0), oldLines,
      newStart: newBegin + (newLines ? 1 : 0), newLines,
      lines: entries.map(e => ({ equal: ' ', delete: '-', insert: '+' }[e.op]) + e.line),
    };
  });
}

let pairs = 0;
function check(a, b) {
  Object.freeze(a);
  Object.freeze(b);
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  assert.deepEqual(diffLines(a, b), script);
  let inserted = false;
  for (const e of script) {
    if (e.op === 'equal') inserted = false;
    if (e.op === 'insert') inserted = true;
    if (e.op === 'delete') assert.equal(inserted, false);
  }
  for (const context of [0, 1, 2, 3, 10]) {
    const hunks = unifiedHunks(a, b, { context });
    assert.deepEqual(hunks, expectedHunks(script, context));
    for (const hunk of hunks) {
      Object.freeze(hunk.lines);
      Object.freeze(hunk);
    }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
  }
  pairs++;
}

const words = [[]];
for (let length = 1; length <= 4; length++) {
  for (let bits = 0; bits < 2 ** length; bits++) {
    words.push(Array.from({ length }, (_, i) => bits & (1 << i) ? 'x' : ''));
  }
}
for (const a of words) for (const b of words) check(a, b);
let seed = 123456789;
function random(n) {
  seed ^= seed << 13;
  seed ^= seed >>> 17;
  seed ^= seed << 5;
  return (seed >>> 0) % n;
}
const alphabet = ['', 'x', 'y', '+added', '-removed', ' context', '\r', '😀'];
for (let trial = 0; trial < 1500; trial++) {
  const a = Array.from({ length: random(35) }, () => alphabet[random(alphabet.length)]);
  const b = Array.from({ length: random(35) }, () => alphabet[random(alphabet.length)]);
  check(a, b);
}

// Hand-authored global coordinates, zero-width ranges and untouched gaps.
const a = Object.freeze(['a', 'b', 'c', 'd']);
const h = (oldStart, oldLines, newStart, newLines, lines) => ({ oldStart, oldLines, newStart, newLines, lines });
const valid = [h(0, 0, 1, 1, ['+top']), h(2, 1, 2, 0, ['-b']), h(4, 0, 5, 1, ['+bottom'])];
assert.deepEqual(applyHunks(a, valid), ['top', 'a', 'c', 'd', 'bottom']);
assert.deepEqual(applyHunks(a, [h(1, 0, 2, 1, ['+one']), h(1, 0, 3, 1, ['+two'])]), ['a', 'one', 'two', 'b', 'c', 'd']);
assert.deepEqual(applyHunks([''], [h(1, 1, 0, 0, ['-'])]), []);
assert.deepEqual(applyHunks([], [h(0, 0, 1, 1, ['+'])]), ['']);
const copy = applyHunks(a, []);
assert.deepEqual(copy, a);
assert.notEqual(copy, a);
const invalid = [
  null, {}, h(0, 1, 1, 1, [' a']), h(1, 1, 0, 1, [' a']),
  h(-1, 0, 1, 1, ['+x']), h(1.5, 0, 1, 1, ['+x']),
  h(1, -1, 1, 0, []), h(1, 1, 1, -1, []),
  h(5, 1, 5, 1, [' x']), h(5, 0, 6, 1, ['+x']),
  h(1, 1, 2, 1, [' a']), h(1, 1, 1, 1, [' wrong']),
  h(1, 1, 1, 0, ['-wrong']), h(1, 1, 1, 1, ['?a']),
  h(1, 1, 1, 1, ['']), h(1, 1, 1, 1, [null]),
  h(1, 1, 1, 1, [' a', '+x']), h(1, 0, 2, 1, [' a']),
  h(1, 2, 1, 1, [' a']), h(1, 1, 1, 1, ' a'),
];
for (const bad of invalid) assert.throws(() => applyHunks(a, [bad]), /hunk 0 does not apply/);
assert.throws(() => applyHunks(a, [h(2, 1, 1, 0, ['-b']), h(1, 1, 1, 1, [' a'])]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(a, [h(2, 2, 2, 2, [' b', ' c']), h(3, 1, 3, 1, [' c'])]), /hunk 1 does not apply/);
assert.throws(() => applyHunks(a, [valid[0], { ...valid[1], newStart: 3 }]), /hunk 1 does not apply/);
console.log(`Contract checks passed: ${pairs} pairs, five contexts each; malformed and offset hunks rejected.`);

for (const repetitive of [false, true]) {
  const original = Array.from({ length: 20000 }, (_, i) => repetitive ? 'same' : `line ${i}`);
  const changed = original.slice();
  changed.splice(17000, 1, 'replacement');
  changed.splice(5000, 0, 'insertion');
  changed.splice(20, 1);
  const start = performance.now();
  const script = diffLines(original, changed);
  const hunks = unifiedHunks(original, changed);
  const result = applyHunks(original, hunks);
  const milliseconds = performance.now() - start;
  assert.deepEqual(result, changed);
  assert.equal(script.filter(e => e.op !== 'equal').length, 4);
  assert.ok(milliseconds < 1000, `${milliseconds}ms exceeds budget`);
  console.log(`20,000 ${repetitive ? 'repetitive' : 'distinct'} lines: diff + hunks + apply ${milliseconds.toFixed(2)}ms`);
}
